CREATE TABLE IF NOT EXISTS dm_index_n.index_grp2_std_ast_bef_covt_mth_apd( grp_id1 STRING COMMENT '组合ID1', grp_id2 STRING COMMENT '组合ID2',  index_val STRING COMMENT '指标值' , data_time STRING COMMENT '数据时间', modify_operator STRING COMMENT '修改人', modify_time STRING COMMENT '修改时间', status STRING COMMENT '状态 1：可用 0：已失效', index_id STRING COMMENT '指标代码' ) COMMENT '客户*机构_标准资产_折算前&产品户比例切分&异地开户切分&剔除司法冻结户&剔除特定客户_当月日均&每日更新过去6个月数据_无备注信息' PARTITIONED BY ( busi_mon STRING COMMENT '业务月份', tag_id STRING COMMENT '标签ID' ) STORED AS ORC;